var ENT=[["Chronicler", "Signature Chronicler pillar of the Commit Generator framework."], ["Merger", "Signature Merger pillar of the Commit Generator framework."], ["Brancher", "Signature Brancher pillar of the Commit Generator framework."], ["Bisector", "Signature Bisector pillar of the Commit Generator framework."], ["Signer", "Signature Signer pillar of the Commit Generator framework."], ["Blamer", "Signature Blamer pillar of the Commit Generator framework."], ["Herald", "Signature Herald pillar of the Commit Generator framework."]];
